def workflow(incident\_priority: str):
   # Check if the incident priority is critical
   if incident\_priority.upper() == "CRITICAL":
       # If critical, send an email using Outlook instead of a Slack message
       Microsoft\_Exchange\_Messages\_\_2\_0\_0\_\_SENDOUTLOOK\_Messages(
           to="it-team@example.com",
           subject="CRITICAL Incident: Please Address Immediately",
           body="A critical incident has been reported in ServiceNow. Please tend to it immediately.",
       )
   else:
       # For non-critical incidents, create a Jira issue
       Jira\_Issue\_\_2\_0\_0\_\_create\_Issue(
           summary="Incident Reported in ServiceNow",
           description=f"Incident Priority: {incident\_priority}",
       )

       # And create a GitHub issue
       GitHub\_Issue\_\_3\_0\_0\_\_create\_Issue(
           title=f"ServiceNow Incident: {incident\_priority}",
           body="An incident has been reported in ServiceNow. Please review and address as needed.",
       )

